mapper.select:
select a.id as id, a.title as title, c.name as category_name, a.capacity as capacity, a.signed_count as signed_count, a.status as status, (select count(*) from activity_registration r where r.activity_id = a.id and r.status in (1, 2, 4)) as joined_count from activity a left join activity_category c on c.id = a.category_id
a.organizer_id = #{organizerId}
order by joined_count desc, a.id desc limit #{limit}
